SELECT COUNT(*) AS count FROM AUD_TASK_ITEMS t WHERE (EXISTS (SELECT 1 FROM AUD_PIPELINES_RUN_LOG r JOIN CFG_PIPELINES p ON p.PIPELINE_ID=r.PIPELINE_ID WHERE p.PROJECT_ID=:project_id AND r.STATUS IN ('SUCCESS','FAILED','SKIPPED','CANCELLED') AND r.END_DATE < :cutoff AND EXISTS (SELECT 1 FROM AUD_TASK_RUN_LOG tr WHERE tr.PIPELINE_RUN_ID=r.PIPELINE_RUN_ID AND tr.TASK_RUN_ID=t.TASK_RUN_ID))) AND t.STATUS IN ('SUCCESS','FAILED','SKIPPED','CANCELLED') AND t.ENDED_AT < :cutoff
